118		}
119	
120		// Diff the two test images to find blocks that differ
121		for (int y = 0; y < ref_dim_y; y++)
122		{
123			for (int x = 0; x < ref_dim_x; x++)
124			{
125				int x_block = x / blockdim_x;
126				int y_block = y / blockdim_y;
127	
128				float r_gd = data_good[pix(ref_dim_x, y, x, 4, 0)];
129				float g_gd = data_good[pix(ref_dim_x, y, x, 4, 1)];
130				float b_gd = data_good[pix(ref_dim_x, y, x, 4, 2)];
131				float a_gd = data_good[pix(ref_dim_x, y, x, 4, 3)];
132	
133				float r_bd = data_bad[pix(ref_dim_x, y, x, 4, 0)];
134				float g_bd = data_bad[pix(ref_dim_x, y, x, 4, 1)];
135				float b_bd = data_bad[pix(ref_dim_x, y, x, 4, 2)];
136				float a_bd = data_bad[pix(ref_dim_x, y, x, 4, 3)];
137	
138				float r_diff = (r_gd - r_bd) * (r_gd - r_bd);
139				float g_diff = (g_gd - g_bd) * (g_gd - g_bd);
140				float b_diff = (b_gd - b_bd) * (b_gd - b_bd);
141				float a_diff = (a_gd - a_bd) * (a_gd - a_bd);
142	
143				float diff = abs(r_diff) + abs(g_diff) + abs(b_diff) + abs(a_diff);
144				errorsums[pix(x_blocks, y_block, x_block, 1, 0)] += diff;
145			}
146		}
